/* Pure applicability rules. Inputs retain the original Chinese commodity and exceptions. */
(function(root){
function parseFood(food){const marker=food.lastIndexOf('除外');if(marker<0)return {base:food,except:[]};const open=food.search(/[([]/);if(open<0)return {base:food,except:[],unparsed:true};const base=food.slice(0,open);const body=food.slice(open+1,marker);let depth=0,word='',parts=[];for(const ch of body){if('(['.includes(ch))depth++;if(')]'.includes(ch))depth--;if(depth===0&&'、和'.includes(ch)){if(word)parts.push(word);word=''}else word+=ch}if(word)parts.push(word);return {base,except:parts}}
function membership(c){return new Set([c.zh,...c.groups,...c.aliases.filter(v=>/[\u4e00-\u9fff]/.test(v))])}
function matches(row,c){const parsed=parseFood(row.food),names=membership(c);if((row.category!==c.category&&!(c.extraCategories||[]).includes(row.category))||!names.has(parsed.base)||parsed.unparsed)return null;if(parsed.except.some(v=>names.has(v)))return null;if(row.category!==c.category&&parsed.base!==c.zh)return null;const direct=parsed.base===c.zh||c.aliases.some(v=>/[\u4e00-\u9fff]/.test(v)&&v===parsed.base);return {row,match:direct?'direct':'group',base:parsed.base,score:direct?100:Math.max(1,c.groups.indexOf(parsed.base)+1)}}
function resolve(rows,c){const found=rows.map(r=>matches(r,c)).filter(Boolean),by=new Map();for(const x of found){const list=by.get(x.row.pesticideId)||[];list.push(x);by.set(x.row.pesticideId,list)}const out=[];for(const list of by.values()){const max=Math.max(...list.map(v=>v.score));const chosen=list.filter(v=>v.score===max);const conflict=new Set(chosen.map(v=>v.row.mrl+'|'+v.row.qualifier)).size>1;for(const x of chosen)out.push({...x.row,match:x.match,cropId:c.id,conflict,otherMatches:list.length-chosen.length})}return out}
function compare(value,limit,mode='number',loq=null){if(!Number.isFinite(limit)||limit<0)return {status:'review',text:'No numeric limit is available.'};if(mode==='nd'){if(loq===null||!Number.isFinite(loq)||loq<=0)return {status:'review',text:'Enter the laboratory reporting limit for a non-detect. A non-detect is not zero.'};return loq<=limit?{status:'review',text:'The reporting limit is at or below the displayed MRL. Confirm the method, residue definition and reporting convention with your laboratory.'}:{status:'review',text:'The reporting limit exceeds the MRL; this non-detect cannot establish that residues are below the MRL.'}}if(value===null||!Number.isFinite(value)||value<0)return {status:'review',text:'Enter a valid non-negative quantified result.'};return value>limit?{status:'above',text:'Above the displayed limit by '+Number((value-limit).toPrecision(6))+' mg/kg.'}:value===limit?{status:'equal',text:'Equal to the displayed limit. Measurement uncertainty and applicability still need review.'}:{status:'below',text:'Below the displayed limit. This numerical comparison is not an import clearance decision.'}}
// Rows whose food name Annex A does not define (e.g. 甘蓝) but which a crop name contains. Shown for review only, never applied.
function unmapped(rows,c,known){return rows.filter(r=>{if(r.category!==c.category)return false;const p=parseFood(r.food);return !p.unparsed&&!known.has(p.base)&&[c.zh,...c.groups].some(n=>n!==p.base&&n.includes(p.base))})}
const api={parseFood,membership,matches,resolve,compare,unmapped};root.MRL=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
